python3 - <<'PY'
p='src/types/checker/type_compat/unions.rs'
s=open(p).read()
old = """    /// If `declared_ty` is a generic array hint and `actual_ty` is a concrete array or
    /// assoc-array, returns `actual_ty` (specialization). Otherwise returns `declared_ty`.
    /// Used to sharpen untyped `array` parameters when the actual argument type is known."""
new = """    /// Returns the type a BY-REFERENCE array parameter must carry, or `None` when neither the
    /// parameter nor the argument is an array.
    ///
    /// A by-reference parameter is compiled against the CALLER's storage, so it may never adopt a
    /// call site's concrete element type the way a by-value parameter does. A body compiled for
    /// `array<int>` that widens mid-call — a loop storage contract, an element write of a `Mixed`
    /// value, an `$a[] =` of a string — rewrites the caller's array to boxed slots while the
    /// caller still reads raw ones, and prints ADDRESSES.
    ///
    /// The container KIND comes from the parameter when it already has one, so a declared `array`
    /// hint is not turned into an `AssocArray` by one call site; only the ELEMENT widens.
    pub(crate) fn by_ref_array_param_type(
        param_ty: &PhpType,
        actual_ty: &PhpType,
    ) -> Option<PhpType> {
        let kind = match param_ty {
            PhpType::Array(_) | PhpType::AssocArray { .. } => param_ty,
            _ => actual_ty,
        };
        match kind {
            PhpType::Array(_) => Some(PhpType::Array(Box::new(PhpType::Mixed))),
            PhpType::AssocArray { key, .. } => Some(PhpType::AssocArray {
                key: key.clone(),
                value: Box::new(PhpType::Mixed),
            }),
            _ => None,
        }
    }

    /// If `declared_ty` is a generic array hint and `actual_ty` is a concrete array or
    /// assoc-array, returns `actual_ty` (specialization). Otherwise returns `declared_ty`.
    /// Used to sharpen untyped `array` parameters when the actual argument type is known."""
assert s.count(old)==1
open(p,'w').write(s.replace(old,new))
print('helper added')
